entries[31807] = { ["name"] = "Naturalisierte Munition", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Übernimmt 3 min lang die Kontrolle über eine Teufelskanone bei der Schwelle des Todes. Verwendet die Artillerie, um das Warptor anzugreifen und den Flammenwerfer, um instabile Teufelswichtel und Leerenhunde anzugreifen. (1 Min Abklingzeit)" }
