entries[32756] = { ["name"] = "Gyrobalancierter Khoriumzerstörer", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n148 - 275 Schaden Tempo 2.80\n(75.54 Schaden pro Sekunde)\n+27 Ausdauer\n\nGelber Sockel\nSockelbonus: +3 Ausdauer\n\nHaltbarkeit 90 / 90\nBenötigt Stufe 70" }
entries[32757] = { ["name"] = "Gesegnetes Medaillon von Karabor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHals\n+49 Ausdauer\n+40 Schattenwiderstand\nBenutzen: Teleportiert den Träger an die Stufen von Illidans Festung. (15 Min Abklingzeit)\n\"Dieser Gegenstand, einst von einem Kleriker von Karabor getragen, gewährt dem Träger Einlass in den Schwarzen Tempel.\"" }
entries[32758] = { ["name"] = "Eau de Schläger", ["text"] = "Benutzen: Schüttet es über Euren gesamten Körper, um wie ein kultivierter Oger zu riechen. Sämtliche Wesen werden Euch sicherlich schon von weitem bemerken.\n\nNur im Schergrat anwendbar.\n\"Ein erlesener Duft für den anspruchsvollen Oger.\"" }
entries[32759] = { ["name"] = "Beschleunigermodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wird benutzt, um die Steuerungen für Protonenbeschleunigung am Landeplatz von Bash'ir zu aktivieren.\"" }
entries[32760] = { ["name"] = "Pfeil des Machognoms", ["text"] = "Wird beim Aufheben gebunden\nMunition Pfeil\nVerursacht 53 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 70\n\"Befiedert von Andy \"Der Machognom\" Savage.\"" }
entries[32761] = { ["name"] = "Die Offizierskugel", ["text"] = "Wird beim Aufheben gebunden\nMunition Kugel\nVerursacht 53 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 70\n\"Mächtiges Badabumm.\"" }
entries[32762] = { ["name"] = "Rulksters Hirnsaft", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. (1 Min Abklingzeit)\n\"Sei kein Dummkopf, trink deinen Hirnsaft!\"" }
entries[32763] = { ["name"] = "Rulksters Geheimsoße", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. (1 Min Abklingzeit)\n\"Trinkt und lebt.\"" }
entries[32764] = { ["name"] = "Flaschataurens himmlisches Gebräu", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht 1 hour lang die maximale Gesundheit um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die flaschenhafte Essenz des mythenumrankten Wesens!\"" }
entries[32765] = { ["name"] = "Flaschataurens Tränen", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Angriffskraft 1 hour lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die destillierten Tränen des schwer zu fassenden Flaschatauren.\"" }
entries[32766] = { ["name"] = "Flaschataurens Fläschchen der Flaschität", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Manaregeneration 1 hour lang um 31 Mana alle 5 Sekunden. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Trägt das Zeichen des Flaschatauren.\"" }
entries[32767] = { ["name"] = "Flaschataurens Fläschchen der ziemlich beeindruckenden Macht", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 hour lang um 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Nicht überragend, aber auch nicht so schlecht.\"" }
entries[32768] = { ["name"] = "Zügel des Rabenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\nBeschwört ein riesiges Rabenreittier oder gibt es frei. Das ist ein sehr schnelles Reittier." }
entries[32769] = { ["name"] = "Gürtel des Rabenfürsten", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n164 Rüstung\n+25 Stärke\n+19 Beweglichkeit\n+22 Ausdauer\n\nRoter Sockel\nBlauer Sockel\nSockelbonus: +3 Beweglichkeit\n\nHaltbarkeit 35 / 35\nBenötigt Stufe 70" }
entries[32770] = { ["name"] = "Silberkreuz der Himmelswache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 70\nBenötigt Himmelswache der Sha'tari\n- Ehrfürchtig\nAnlegen: Erhöht die kritische Trefferwertung um 34.\nAnlegen: Chance von 50%, Eure Angriffskraft 30 sec lang um 140 zu erhöhen, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann innerhalb von 10 Sek. nur einmal auftreten. (Procchance: 50%, 10s Abklingzeit)" }
entries[32771] = { ["name"] = "Luftfahrerschleife des Edelmuts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 70\nBenötigt Himmelswache der Sha'tari\n- Ehrfürchtig\nAnlegen: Erhöht die kritische Trefferwertung um 34.\nAnlegen: Chance von 50%, die Zaubermacht 30 sec lang um 80 zu erhöhen, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann innerhalb von 10 Sek. nur einmal auftreten. (Procchance: 50%, 10s Abklingzeit)" }
