entries[32773] = { ["name"] = "Dietrich von Bash'ir", ["text"] = "Benutzen: Öffnet die Stasiskammer des Astraleums." }
entries[32774] = { ["name"] = "Die schwarze Perle", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nFinger\n+33 Ausdauer\nBenötigt Stufe 65\nAnlegen: Erhöht die Zaubermacht um 25." }
entries[32775] = { ["name"] = "Tiefseeperle", ["text"] = "Benötigt Stufe 50\nBenutzen: Verschluckt die Perle, verleiht dem Anwender die Fähigkeit unter Wasser zu atmen und erhöht das Schwimmtempo deutlich. Hält 30 sec lang an. (1 Min Abklingzeit)" }
entries[32776] = { ["name"] = "Krone der Meerhexe", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n127 Rüstung\n+42 Ausdauer\n+20 Intelligenz\n+20 Willenskraft\n\nRoter Sockel\nBlauer Sockel\nBlauer Sockel\nSockelbonus: +5 Zaubermacht\n\nHaltbarkeit 50 / 50\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubermacht um 23." }
entries[32777] = { ["name"] = "Kronks Grabbelsack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wer weiß schon, was da drin ist? Hoffentlich eine Rune der Dunkelheit!\"\n<Zum Öffnen rechtsklicken>" }
