entries[32871] = { ["name"] = "Hörner der Illidari", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n853 Rüstung\n+24 Ausdauer\n\nGelber Sockel\nBlauer Sockel\nBlauer Sockel\nSockelbonus: +6 Ausdauer\n\nHaltbarkeit 70 / 70\nAnlegen: Erhöht die Verteidigungswertung um 29.\nAnlegen: Erhöht den Blockwert Eures Schildes um 66." }
entries[32872] = { ["name"] = "Disziplinarrute der Illidari", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n107 - 199 Schattenschaden Tempo 1.40\n(109.29 Schaden pro Sekunde)\n+9 Ausdauer\n\nBlauer Sockel\nSockelbonus: +2 Zaubermacht\n\nHaltbarkeit 55 / 55\nAnlegen: Erhöht die Zaubermacht um 13." }
entries[32882] = { ["name"] = "Höllenfeuergeschoss", ["text"] = "Wird beim Aufheben gebunden\nMunition Kugel\nVerursacht 37 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 68\nBenötigt Thrallmar\n- Respektvoll" }
