entries[32888] = { ["name"] = "Die Relikte von Terokk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Isfars Notizen zur Lage der Relikte von Terokk\"\n<Zum Lesen rechtsklicken>" }
entries[32895] = { ["name"] = "Schriftrolle des Mahlstroms", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Stellt 5 Male der Illidari her.\n\"Eine mit der Magie des Schlangenschreins erfüllte Schriftrolle.\"" }
